// Кейсы: .qa/tests/devices/DEV-014.md (шаги 4–5), DEV-015.md (шаги 2, 5, 7) · план: .qa/e2e-app/specs/app.md (1.35)
// Главный iPhone: статус строки второго телефона — ровно один из «מקבל התרעות» / «התרעות כבויות»;
// при «מקבל התרעות» — «שליחת התרעת בדיקה» → «התרעת בדיקה נשלחה לטלפון אחד».
// Побочный эффект: тестовое уведомление на второй телефон (данные не меняются). Доставку на второй Appium не видит — DEV-014 шаг 6 вручную.
import { by, assert, skip } from '../../lib/appium.mjs';
import { onHome, openTab, waitEnabled } from '../../lib/banci.mjs';
import { openDevices, secondRowText, SECOND, STATUS_ON, STATUS_OFF } from './devices-helpers.mjs';

export const name = '«מכשירים»: у второго телефона ровно один статус «מקבל התרעות»/«התרעות כבויות»; при «מקבל התרעות» тестовая тревога → «התרעת בדיקה נשלחה לטלפון אחד» #83f7f9 @iphone @app';

export default async function (app) {
  // 1. «מכשירים» → строка «מכשיר נוסף».
  await openDevices(app);
  await app.scrollTo(SECOND, { max: 3, what: 'строка «מכשיר נוסף»' }).catch(() => null);
  const row = await secondRowText(app);
  if (row === null) skip('в аккаунте нет дополнительного телефона — подключить второй по QR (DEV-012 шаги 5–7)');
  const on = row.includes(STATUS_ON) || (await app.exists(by.contains(STATUS_ON)));
  const off = row.includes(STATUS_OFF) || (await app.exists(by.contains(STATUS_OFF)));
  console.log(`     строка второго: «${row}»`);
  assert(on !== off, `у второго телефона ровно один статус «${STATUS_ON}» или «${STATUS_OFF}» (сейчас: ${on ? 'מקבל' : ''}${on && off ? ' + ' : ''}${off ? 'כבויות' : ''}${!on && !off ? 'ни одного' : ''})`);
  await app.screenshot(`83f7f9-auto-devices-${on ? 'on' : 'off'}`);

  if (off) {
    await app.restart();
    skip('у второго телефона «התרעות כבויות» — отправку проверяем только при «מקבל התרעות» (включить уведомления на втором — DEV-015 шаг 4)');
  }

  // 2. «חשבון» → «התרעות וצפצוף» → «שליחת התרעת בדיקה».
  await app.restart();
  await onHome(app);
  await openTab(app, 'חשבון');
  await (await app.scrollTo(by.begins('התרעות וצפצוף'), { what: 'строка «התרעות וצפצוף» в «חשבון»' })).click();
  const btn = await app.scrollTo(by.begins('שליחת התרעת בדיקה'), { what: '«שליחת התרעת בדיקה»' });
  await waitEnabled(btn, true, { what: '«שליחת התרעת בדיקה»' });
  await btn.click();

  // 3. Итог отправки: доставлено на один телефон (а не «אין טלפונים אחרים עם התרעות פעילות» — суть бага #83f7f9).
  const result = `(${by.contains('התרעת בדיקה נשלחה')}) OR (${by.contains('אין טלפונים אחרים')})`;
  await app.waitFor(result, { timeout: 20000, what: 'сообщение об итоге тестовой тревоги' });
  assert(!(await app.exists(by.contains('אין טלפונים אחרים'))), 'нет «אין טלפונים אחרים עם התרעות פעילות» при статусе «מקבל התרעות»');
  await app.waitFor(by.contains('התרעת בדיקה נשלחה לטלפון אחד'), { what: '«התרעת בדיקה נשלחה לטלפון אחד»' });
  await app.screenshot('83f7f9-auto-test-alert-sent');
  await app.restart();
}
